procedure.step:
      Wrap the entire body in an IIFE with try/catch:

(function erpPageName() {
  try {
    // …body…
  } catch (e) {
    console.error("[erpPageName]", e);
  }
})();

      Add null guards for every DOM query:

const el = document.getElementById("target");
if (!el) return;

      Use it if available; otherwise fall back to alert():

if (toast) toast("error", msg);
else alert(msg);

      In the JS file, resolve the message using the full algorithm:

const errFb = "# ERROR";
const dataClientLocalized = "data-client-localized";
const dataGuardMsg = "data-guard-msg";
let msg = errFb;

if (
  el.getAttribute("data-sv-localized") === "true" ||
  el.getAttribute(dataClientLocalized) === "true"
)
  msg = el.getAttribute(dataGuardMsg) || errFb;
else {
  let lang = (
    window.sessionStorage.getItem("erp-np-lang") ||
    document.documentElement.lang ||
    "en"
  )
    .toLowerCase()
    .replace(/_/g, "-");
  lang = lang === "pt-br" ? lang : lang.slice(0, 2);
  const msgKey = /* context-specific key */;
  msg =
    window.translations?.[lang]?.[msgKey] ||
    el.getAttribute(dataGuardMsg) ||
    window.translations?.["en"]?.[msgKey] ||
    errFb;
  if (msg !== errFb) {
    el.setAttribute(dataGuardMsg, msg);
    el.setAttribute(dataClientLocalized, "true");
  }
}

      Create the MutationObserver and start observing:

const observer = new MutationObserver(mutations => {
  for (const m of mutations) {
    if (!document.contains(targetEl)) {
      observer.disconnect();
      return;
    }
    // …handle mutations…
  }
});
observer.observe(targetEl, { childList: true, subtree: true });
